(async function submit(choice,received){
  const records=load("decision_bench_records"), cases=load("decision_bench_cases");
  async function routeOne(c){
    const started=Date.now();let result,error=null;
    try{result=await tools.mcp__harness_router__route(c.input);}catch(e){error=String(e);}
    const ended=Date.now();
    let decision=result?.structuredContent??null;
    if(!decision&&result?.content){for(const block of result.content){if(block.type==="text"){try{decision=JSON.parse(block.text);break;}catch{}}}}
    return {started_at_ms:started,ended_at_ms:ended,elapsed_ms:ended-started,decision,error,raw:result??null};
  }
  const active=load("decision_bench_active");
  if(active){
    if(typeof choice!=="string"||!active.case.input.tools.some(t=>t.name===choice)) throw Error("Invalid choice");
    const native={started_at_ms:active.started,ended_at_ms:received,elapsed_ms:received-active.started,tool:choice};
    store("decision_bench_active",null);
    const router=active.router??await routeOne(active.case);
    records.push({...active.case,native,router});
    store("decision_bench_records",records);
    store("decision_bench_index",records.length);
    if(records.length%6===0){
      text({block_complete:records.length,total:cases.length,router_fallbacks:records.filter(r=>r.router.decision?.fallback).length,router_errors:records.filter(r=>r.router.error||r.router.raw?.isError).length});
      return;
    }
  }else if(choice!==null){throw Error("No active trial");}
  const index=load("decision_bench_index");
  if(index>=cases.length){text({complete:true,trials:records.length});return;}
  const c=cases[index];
  const router=c.order==="router_first"?await routeOne(c):null;
  const started=Date.now();
  store("decision_bench_active",{case:c,router,started});
  text({trial:c.trial,total:cases.length,instruction:"Choose the single best next tool. Record only its name through the submission helper; do not execute it.",...c.input});
})
